void sobel(const uint8_t *input, uint8_t *output, int width, int height)
{
  /* Knob Variables Declaration Start */
  float loop_perforation_factor = 1.0;  // Range: 0.1 to 1.0, Real
  int quantize_enabled = 0;            // Boolean (0 or 1)
  int shift_bits = 0;                  // Range: 0 to 4, Integer
  int early_exit_enabled = 0;          // Boolean (0 or 1)
  int max_iterations = width * height; // Integer, max iterations for early exit
  int truncate_enabled = 0;            // Boolean (0 or 1)
  /* Knob Variables Declaration End */

  int iteration_count = 0; // For early-exit approximation

  // Truncate the loop iterations based on loop_perforation_factor
  int truncated_height = height * loop_perforation_factor;
  int truncated_width = width * loop_perforation_factor;

  for (int y = 0; y < truncated_height; y++) { /* @Approximation: Loop Perforation */
    for (int x = 0; x < truncated_width; x++) { /* @Approximation: Loop Perforation */

      if (early_exit_enabled && iteration_count >= max_iterations) { /* @Approximation: Early Exit */
        return;
      }

      if (x == 0 || x == width - 1 || y == 0 || y == height - 1) {
        output[y * width + x] = 0;
        continue;
      }

      int p00 = input[(y-1)*width + (x-1)];
      int p01 = input[(y-1)*width +  x   ];
      int p02 = input[(y-1)*width + (x+1)];
      int p10 = input[ y   *width + (x-1)];
      int p12 = input[ y   *width + (x+1)];
      int p20 = input[(y+1)*width + (x-1)];
      int p21 = input[(y+1)*width +  x   ];
      int p22 = input[(y+1)*width + (x+1)];

      int gx = -p00 + p02 - 2*p10 + 2*p12 - p20 + p22;
      int gy =  p00 + 2*p01 + p02 - p20 - 2*p21 - p22;

      int mag;
      if (truncate_enabled) { /* @Approximation: Truncated Computations */
        mag = (gx + gy); // Simplified gradient magnitude
      } else {
        mag = abs(gx) + abs(gy);
      }

      if (mag > 255) mag = 255;

      if (quantize_enabled) { /* @Approximation: 4-Bit Quantization */
        mag = mag >> shift_bits;
      }

      output[y * width + x] = (uint8_t)mag;

      iteration_count++;
    }
  }
}
